import { fileURLToPath } from 'node:url';
import js from '@eslint/js';
import tseslint from 'typescript-eslint';
import reactHooks from 'eslint-plugin-react-hooks';
import reactRefresh from 'eslint-plugin-react-refresh';
import jsxA11y from 'eslint-plugin-jsx-a11y';
import globals from 'globals';
import rutekit from 'eslint-plugin-rutekit';

const rootDir = fileURLToPath(new URL('.', import.meta.url));

export default tseslint.config(
  {
    ignores: [
      '**/node_modules/**',
      '**/dist/**',
      '**/coverage/**',
      '**/.vite/**',
      '**/*.tsbuildinfo',
      // Generated by `msw init` and by tooling; never hand-edited (AP-6).
      'apps/web/public/mockServiceWorker.js',
    ],
  },

  js.configs.recommended,

  // ── TypeScript: type-aware linting everywhere ──────────────────────────
  {
    files: ['**/*.{ts,tsx}'],
    extends: [...tseslint.configs.recommendedTypeChecked],
    languageOptions: {
      parserOptions: {
        projectService: true,
        tsconfigRootDir: rootDir,
      },
    },
    rules: {
      '@typescript-eslint/no-explicit-any': 'error',
      '@typescript-eslint/no-non-null-assertion': 'error',
      '@typescript-eslint/consistent-type-imports': [
        'error',
        { prefer: 'type-imports', fixStyle: 'inline-type-imports' },
      ],
      '@typescript-eslint/ban-ts-comment': [
        'error',
        {
          'ts-ignore': true,
          'ts-nocheck': true,
          'ts-check': false,
          'ts-expect-error': 'allow-with-description',
          minimumDescriptionLength: 10,
        },
      ],
      '@typescript-eslint/switch-exhaustiveness-check': 'error',
      '@typescript-eslint/no-unused-vars': [
        'error',
        { argsIgnorePattern: '^_', varsIgnorePattern: '^_', caughtErrorsIgnorePattern: '^_' },
      ],
      // The `no-unsafe-*` family assumes third-party boundaries are typed. Ours are
      // validated at runtime with Zod (TS-8), and library callbacks (MSW, router)
      // legitimately surface `any`. Keeping them on would drown real findings.
      '@typescript-eslint/no-unsafe-assignment': 'off',
      '@typescript-eslint/no-unsafe-member-access': 'off',
      '@typescript-eslint/no-unsafe-argument': 'off',
      '@typescript-eslint/no-unsafe-call': 'off',
      '@typescript-eslint/no-unsafe-return': 'off',
      '@typescript-eslint/restrict-template-expressions': [
        'error',
        { allowNumber: true, allowBoolean: true },
      ],
      // Real bugs, worth the type-checker cost.
      '@typescript-eslint/no-floating-promises': 'error',
      '@typescript-eslint/no-misused-promises': 'error',
      '@typescript-eslint/await-thenable': 'error',
      '@typescript-eslint/require-await': 'error',

      eqeqeq: ['error', 'always', { null: 'ignore' }],
      'no-console': ['warn', { allow: ['warn', 'error'] }],
      'no-restricted-syntax': [
        'error',
        {
          selector: 'TSEnumDeclaration',
          message: 'Use an `as const` object plus a derived union type (TS-9), not an enum.',
        },
      ],
    },
  },

  // ── Frontend: design-system enforcement (R3) ───────────────────────────
  {
    files: ['apps/web/src/**/*.{ts,tsx}'],
    plugins: { rutekit },
    rules: {
      'rutekit/no-hardcoded-color': 'error',
      'rutekit/no-hardcoded-radius': 'error',
      'rutekit/no-hardcoded-duration': 'error',
      'rutekit/no-inline-style': 'error',
    },
  },

  // ── Frontend: React ────────────────────────────────────────────────────
  {
    files: ['apps/web/src/**/*.{ts,tsx}'],
    plugins: { 'react-hooks': reactHooks, 'react-refresh': reactRefresh },
    languageOptions: { globals: { ...globals.browser } },
    rules: {
      ...reactHooks.configs.recommended.rules,
      'react-refresh/only-export-components': ['warn', { allowConstantExport: true }],
    },
  },

  // ── Frontend: accessibility (NFR-6, D5) ────────────────────────────────
  {
    // The structural half of the a11y audit. Contrast is measured from the design
    // tokens in `apps/web/test/contrast.test.ts`; keyboard reachability is not
    // checkable by a linter at all. What a linter *can* catch is the class of
    // mistake that is invisible in review and obvious to a screen reader: a
    // clickable `div` with no role, an image with no alternative, a label that
    // points at nothing, an `aria-*` attribute spelled wrong.
    //
    // `recommended` rather than every rule: the strict set includes opinions about
    // heading order and landmark structure that this console deliberately does not
    // follow (it has one `main`, and page headers are not all `h1`).
    files: ['apps/web/src/**/*.{ts,tsx}'],
    extends: [jsxA11y.flatConfigs.recommended],
    rules: {
      // A decorative icon is `aria-hidden` and its label lives on the control, so
      // this rule would fire on every icon-only button that is already correct.
      'jsx-a11y/control-has-associated-label': 'off',

      // ── The five rules this codebase does not fit, each with its reason ──
      //
      // Every one of these was checked against the code before being turned off.
      // A rule silenced without a reason is a rule nobody will ever re-examine;
      // a rule silenced with one is a decision that can be revisited.

      // `role="list"` on a `<ul>` looks redundant and is not: Tailwind's
      // preflight sets `list-style: none`, and WebKit removes a list's implicit
      // role when its marker is gone. The explicit role is the standard repair —
      // without it VoiceOver announces the console's lists as plain groups.
      'jsx-a11y/no-redundant-roles': 'off',

      // The controls are *inside* the label (`<label>…<Switch /></label>`), which
      // associates them correctly, but the rule does not follow through a custom
      // component like `Switch` or `Field` to find the input it renders.
      'jsx-a11y/label-has-associated-control': 'off',

      // Generated media — a Studio render — has no caption track to offer, and
      // inventing an empty one would satisfy the rule while telling a screen
      // reader nothing.
      'jsx-a11y/media-has-caption': 'off',

      // The icon picker is a textbook ARIA radiogroup: roving `tabIndex` on the
      // radios, arrow keys handled on the group and bubbled from whichever radio
      // has focus. The group itself must *not* be focusable in that pattern, so
      // the rule's complaint is the opposite of the correct behaviour.
      'jsx-a11y/interactive-supports-focus': 'off',

      // The flagged elements — the usage chart and a log row — both carry an
      // `onKeyDown` beside their mouse handlers, so they are reachable and
      // operable from the keyboard. The rule sees a `role="img"` or a
      // `role="listitem"` and stops there.
      'jsx-a11y/no-noninteractive-element-interactions': 'off',
      'jsx-a11y/no-noninteractive-tabindex': 'off',
    },
  },

  // ── Node contexts ──────────────────────────────────────────────────────
  {
    files: [
      'packages/**/*.ts',
      'apps/server/**/*.ts',
      'tools/**/*.js',
      // The benchmark provider promptfoo loads. Plain CommonJS with no imports,
      // so it needs the Node globals spelled out here rather than through a
      // package of its own.
      'tools/**/*.cjs',
      '*.config.{js,ts}',
      'apps/*/vite.config.ts',
      'apps/*/vitest.config.ts',
      'packages/*/vitest.config.ts',
    ],
    languageOptions: { globals: { ...globals.node } },
  },

  // ── Tests ──────────────────────────────────────────────────────────────
  {
    files: ['**/*.test.{ts,tsx}', '**/test/**/*.{ts,tsx}', '**/*.spec.{ts,tsx}'],
    rules: {
      '@typescript-eslint/no-non-null-assertion': 'off',
      '@typescript-eslint/no-unsafe-assignment': 'off',
      'no-console': 'off',
    },
  },
);
